    prompt: { d: "M5.25 6.25 7 8l-1.75 1.75M8.5 10h2.25" },
  },
  branch: {
    a: { d: "M6.25 4a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    b: { d: "M6.25 12a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    c: { d: "M12.25 5a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    trunk: { d: "M5 5.25v5.5" },
    twig: { d: "M11 6.25v.5a3 3 0 0 1-3 3H7.25a2.25 2.25 0 0 0-2.25 1" },
  },
  /* An amount of effort: a dial and its needle. */
  gauge: {
    dial: { d: "M2.75 11.75a5.25 5.25 0 1 1 10.5 0" },
    needle: { d: "M8 11.75l2.5-3.5" },
  },
  /* A panel with its column on the other side: show or hide a side panel at the end. */
  panel: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    rail: { d: "M9.75 2.75 L9.75 13.25" },
  },
  /* What happened to a file: one rounded square, and inside it a plus, a
     dot, a minus or an arrow. They share the square and the bar, so a file
     whose change kind moves morphs only the mark. */
  "diff-added": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    stem: { d: "M8 10.5 L8 5.5" },
  },
  "diff-modified": {
    frame: { d: CHANGE_FRAME },
    dot: { d: "M8 8 L8.01 8", block: true },
  },
  "diff-removed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
  },
  "diff-renamed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    head: { d: "M8.5 6 L10.5 8 L8.5 10" },
  },
} satisfies Record<string, Record<string, Stroke>>;

export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

@layer components {
  /* Base UI's Positioner places this element; the surface inside it animates. */
  .positioner {
    z-index: 60;
    max-width: min(280px, calc(100vw - 16px));
  }

  .surface {
    position: relative;
    display: flex;
    align-items: baseline;
    gap: var(--ui-space-2);
    width: max-content;
    max-width: 100%;
    box-sizing: border-box;
    padding: var(--ui-space-1) var(--ui-space-2);
    border-radius: var(--ui-radius-sm);
    background: var(--ui-ink);
    box-shadow: var(--ui-shadow-raised);
    color: var(--ui-on-ink);
    font: var(--ui-weight-medium) var(--ui-text-sm) / var(--ui-leading-sm) var(--ui-font-sans);
    text-wrap: pretty;
    transform-origin: var(--transform-origin);
    opacity: 1;
    scale: 1;
    filter: none;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-fast) var(--ui-ease-enter),
      filter var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .surface[hidden] {
    display: none;
  }

  .surface[data-starting-style],
  .surface[data-ending-style] {
    opacity: 0;
    scale: 0.97;
    filter: blur(2px);
  }

  .surface[data-ending-style] {
    transition-duration: var(--ui-dur-instant);
    transition-timing-function: var(--ui-ease-exit);
  }

  /* Warm: opened while another tooltip was showing or had just closed. */
  .surface[data-warm] {
    transition-duration: 0s;
  }

  .content {
    min-width: 0;
  }

  .kbd {
    flex-shrink: 0;
    color: var(--ui-on-ink-muted);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    /* Otherwise the mono face on the baseline makes the tooltip taller. */
    line-height: 1;
  }

  /* Base UI sets the arrow's offset along the edge; the SVG points down by default. */
  .arrow {
    position: absolute;
    width: 12px;
    height: 6px;
  }

  .arrow svg {
    display: block;
    width: 12px;
    height: 6px;
    fill: var(--ui-ink);
  }

  .arrow[data-side="top"] {
    top: 100%;
  }

  .arrow[data-side="bottom"] {
    bottom: 100%;
    rotate: 180deg;
  }

  .arrow[data-side="left"] {
    left: calc(100% - 3px);
    rotate: -90deg;
  }

  .arrow[data-side="right"] {
    right: calc(100% - 3px);
    rotate: 90deg;
  }

  @media (prefers-reduced-motion: reduce) {
    .surface {
      transition: none;
    }
    .surface[data-starting-style],
    .surface[data-ending-style] {
      scale: none;
    }
  }
}

"use client";

import {
  cloneElement,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";
import { flushSync } from "react-dom";
import { Tooltip as BaseTooltip } from "@base-ui/react/tooltip";
import styles from "./tooltip.module.css";

type Side = "top" | "bottom" | "left" | "right";
type Align = "start" | "center" | "end";

/** Hover delay before the first tooltip opens. */
const OPEN_DELAY = 500;
/** After a tooltip closes, others open instantly for this long. */
const WARM_WINDOW = 300;

type Handle = { finishExit: () => void; rect: () => DOMRect | undefined };

// Shared by every tooltip on the page, so the component needs no provider.
let active: Handle | null = null;
let exiting: Handle | null = null;
let lastClosedAt = -Infinity;
// Where the previous tooltip sat, so a warm hand-off can slide from there.
let handoff: DOMRect | undefined;

function isWarm() {
  return active !== null || performance.now() - lastClosedAt < WARM_WINDOW;
}

/** A CSS time token in ms. Browsers may report "250ms" as ".25s". */
function ms(value: string, fallback: number) {
  const n = parseFloat(value);
  if (Number.isNaN(n)) return fallback;
  return value.trim().endsWith("ms") ? n : n * 1000;
}

type TriggerProps = { "aria-describedby"?: string };

type TooltipProps = {
  /** What the tooltip says; never the only place something lives. */
  content: ReactNode;
  /** A shortcut shown after the text, like "⌘C". */
  kbd?: string;
  side?: Side;
  align?: Align;
  /** Show an arrow pointing at the trigger. */
  arrow?: boolean;
  /** Link it with `aria-describedby`. Turn off when it only repeats the trigger's `aria-label`. */
  describe?: boolean;
  /** Hover delay before the first tooltip opens, in ms. */
  delay?: number;
  /** One focusable element. Disabled controls need a wrapper; see the guide. */
  children: ReactElement<TriggerProps>;
};

export function Tooltip({
  content,
  kbd,
  side = "top",
  align = "center",
  arrow = false,
  describe = true,
  delay = OPEN_DELAY,
  children,
}: TooltipProps) {
  const tipId = `${useId()}-tooltip`;
  const popupRef = useRef<HTMLDivElement>(null);
  const [triggerEl, setTriggerEl] = useState<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  // Read when the pointer arrives, so Base UI sees a 0ms delay while another tooltip is warm.
  const [warm, setWarm] = useState(false);
  const [instant, setInstant] = useState(false);

  const handle = useRef<Handle>({
    finishExit: () => {
      setInstant(true);
      popupRef.current?.getAnimations().forEach((a) => a.finish());
    },
    // Open or still fading out.
    rect: () => {
      const popup = popupRef.current;
      return popup && +getComputedStyle(popup).opacity > 0 ? popup.getBoundingClientRect() : undefined;
    },
  });

  function onOpenChange(next: boolean) {
    const self = handle.current;
    if (next) {
      const skipEntrance = isWarm();
      const previous = active ?? exiting;
      if (previous && previous !== self) {
        handoff = previous.rect();
        // Don't cross-fade: the outgoing one just goes.
        previous.finishExit();
      }
      active = self;
      exiting = null;
      setInstant(skipEntrance);
    } else {
      if (active === self) {
        active = null;
        lastClosedAt = performance.now();
      }
      exiting = self;
    }
    setOpen(next);
  }

  // A warm hand-off slides from where the previous tooltip sat.
  useEffect(() => {
    if (!open || !instant) return;
    const from = handoff;
    handoff = undefined;
    if (!from || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const frame = requestAnimationFrame(() => {
      const popup = popupRef.current;
      if (!popup) return;
      const to = popup.getBoundingClientRect();
      const dx = from.left + from.width / 2 - (to.left + to.width / 2);
      const dy = from.top - to.top;
      if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return;
      const style = getComputedStyle(popup);
      popup.animate(
        { translate: [`${dx}px ${dy}px`, "0 0"] },
        {
          duration: ms(style.getPropertyValue("--ui-dur-snap"), 250),
          easing: style.getPropertyValue("--ui-ease-snap").trim() || "ease-out",
        },
      );
    });
    return () => cancelAnimationFrame(frame);
  }, [open, instant]);

  useEffect(() => {
    const self = handle.current;
    return () => {
      if (active === self) active = null;
      if (exiting === self) exiting = null;
    };
  }, []);

  const describedBy = [children.props["aria-describedby"], describe ? tipId : null].filter(Boolean).join(" ");

  return (
    <BaseTooltip.Root
      open={open}
      onOpenChange={onOpenChange}
      onOpenChangeComplete={(next) => {
        if (next) return;
        if (exiting === handle.current) exiting = null;
        setInstant(false);
      }}
    >
      <BaseTooltip.Trigger
        ref={setTriggerEl}
        delay={warm ? 0 : delay}
        // Pointer events have continuous priority; flush so the delay is in place before mouseenter.
        onPointerEnter={() => flushSync(() => setWarm(isWarm()))}
        render={cloneElement(children, { "aria-describedby": describedBy || undefined })}
      />
      {/* Kept mounted so `aria-describedby` points at real text even while closed. */}
      <BaseTooltip.Portal
        keepMounted={describe}
        container={triggerEl?.closest<HTMLElement>("dialog[open], [data-theme]") ?? undefined}
      >
        <BaseTooltip.Positioner
          className={styles.positioner}
          side={side}
          align={align}
          sideOffset={arrow ? 10 : 6}
          collisionPadding={8}
        >
          <BaseTooltip.Popup
            ref={popupRef}
            id={tipId}
            role="tooltip"
            className={styles.surface}
            data-warm={instant || undefined}
          >
            <span className={styles.content}>{content}</span>
            {kbd && <kbd className={styles.kbd}>{kbd}</kbd>}
            {arrow && (
              <BaseTooltip.Arrow className={styles.arrow}>
                <svg viewBox="0 0 12 6" aria-hidden="true">
                  <path d="M0 0h12L7.2 5.1a1.6 1.6 0 0 1-2.4 0z" />
                </svg>
              </BaseTooltip.Arrow>
            )}
          </BaseTooltip.Popup>
        </BaseTooltip.Positioner>
      </BaseTooltip.Portal>
    </BaseTooltip.Root>
  );
}

@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

